# LeRoy R. Hafen (dir.), The Mountain Men and the Fur Trade of the Far West, vol. I, Glendale, Arthur H. Clark, 1965.
# PDF du Drive de l'auteur (HISTOIRE_LIVRES/HAFEN_FAR_WEST), lu dans la visionneuse du Drive (406 p.) : seules quelques notices
# de ce volume avaient servi (fiches H001-H005). Corpus « Recherches », préfixe MM1.
from commun import Corpus
def S(aut, tit, p): return f"{aut}, « {tit} », dans Hafen, LeRoy R. (dir.), The Mountain Men and the Fur Trade of the Far West, vol. I, Glendale, Arthur H. Clark, 1965, p. {p}"
MA = lambda p: S("Mattison, Ray H.", "Francis A. Chardon", p)
JA = lambda p: S("Jacobs, Wilbur R.", "Henry Chatillon", p)
CA = lambda p: S("Camp, Charles L.", "James Clyman", p)
C = Corpus('Recherches', 'MM1', MA('225-227'), page_fmt='p. {}')
F = C.F
F('01', "Fourches de la Cheyenne : Chardon hiverne chez les Sioux tetons après ses débuts chez les Osages (1815~-1832)", 'poste', '1815~/1832', -101.700, 44.400, 'h', ['Francis A. Chardon'],
  "D'ascendance française, né à Philadelphie, Francis A. Chardon passe après la guerre de 1812 quelque temps au pays des Osages, dont il apprend la langue et où une Osage lui donne un fils métis. Entré vers 1827-1828 à l'Upper Missouri Outfit, il semble tenir de 1829 à 1832 un poste d'hivernement chez les Sioux tetons aux fourches de la Cheyenne ; en 1832, il est témoin au fort Union du traité avec les Pieds-Noirs.", '225', "Emplacement indicatif.", source=MA('225'))
F('02', "Embouchure de la Milk : Chardon bâtit le fort Jackson (1833)", 'poste', '1833', -106.300, 48.050, 'a', ['Francis A. Chardon'],
  "Après un bref séjour au pays des Pieds-Noirs, Chardon construit en 1833 le fort Jackson près de l'embouchure de la rivière Milk, avant de prendre l'année suivante le commandement du fort Clark, chez les Mandanes, où il tiendra son journal (1834-1839).", '225', "Distinct du fort Jackson de la South Platte (Sarpy et Fraeb).", source=MA('225'))
F('03', "Fort James (Fort Berthold) : Chardon chassé pour la traite de l'alcool, puis mourant devant Palliser (1845-1848)", 'poste', '1845/1848', -101.950, 47.560, 'a', ['Francis A. Chardon', 'John Palliser', 'Alexander Harvey'],
  "Après le massacre de Pieds-Noirs commis avec Alexander Harvey au fort McKenzie (1843) et l'abandon du fort F. A. Chardon de la Judith, Chardon retourne au fort Clark, juge la traite insuffisante et fonde chez les Hidatsas le fort James, plus tard fort Berthold. Expulsé du pays indien en 1846 pour vente illégale d'alcool, il y revient l'année suivante. L'Irlandais John Palliser l'y voit en 1848 puis, lors d'une seconde visite, le trouve mourant de rhumatismes : Chardon lui dicte son testament et meurt ; il est inhumé au fort Pierre. Il laissait un fils osage et des fils de deux de ses trois épouses sioux.", '226-227', source=MA('226-227'))
F('04', "Fort Laramie et le camp de Bull Bear : Henry Chatillon, « Yellow Whiteman », perd son épouse oglala Bear Robe (1846)", 'famille', '1846', -104.558, 42.203, 'a', ['Henry Chatillon', 'Bear Robe', 'Bull Bear', 'Francis Parkman', 'Frank Man-Afraid-of-His-Horse'],
  "Revenu de quatre ans dans les montagnes, Henry Chatillon (v. 1816-1875) est engagé par P. Chouteau Jr. & Co. pour guider Francis Parkman en 1846, de Saint-Louis à Independence, au fort Leavenworth, au fort Laramie, puis au fort Bent. Son épouse indienne, Bear Robe, fille du puissant chef oglala Bull Bear (Mahto-Tatonka), meurt pendant l'été 1846. Les Sioux l'appelaient « Yellow Whiteman » ; son petit-fils sioux, Frank Man-Afraid-of-His-Horse, parlait encore de lui en 1931.", '229-231', source=JA('229-231'))
F('05', "Carondelet : Henry Chatillon, riche puis « usé », reçoit la visite de Parkman (1853-1867)", 'personnage', '1853-02-17/1867', -90.260, 38.560, 'c', ['Henry Chatillon', 'Francis Parkman', 'Quincy A. Shaw', 'Joseph LaBarge'],
  "Chasseur du capitaine de vapeur Joseph LaBarge, Chatillon épouse au début des années 1850 une Blanche et s'établit près de Saint-Louis. Le 17 février 1853, il fait écrire à Parkman qu'ayant amassé cinquante ou soixante mille dollars il n'a que des ennuis, et l'invite avec Quincy A. Shaw à un nouveau voyage aux montagnes. En 1867, Parkman retrouve à Carondelet un Henry « usé », bien moins riche qu'on le disait, mais d'une simplicité d'âme intacte.", '230-231', source=JA('230-231'))
F('06', "La Barge Creek (Wyoming) : le trappeur La Barge tué en montant la garde (printemps 1825)", 'evenement', '1825-04~', -110.200, 42.300, 'a', ['La Barge', 'James Clyman', 'William H. Ashley'],
  "Au printemps 1825, envoyé par Ashley vers les sources de la Green pour rejoindre Jedediah Smith et John H. Weber, le petit parti de cinq hommes de James Clyman est attaqué de nuit par des Indiens sur le ruisseau appelé depuis La Barge Creek : La Barge, qui montait la garde, est tué, et une balle manque de peu Clyman dans son lit.", '244', "Emplacement approximatif sur la La Barge Creek, affluent de la Green.", source=CA('244'))
fiches = C.fiches
